class Solution:
    def countNumberOfWaysToPlaceHouses(self, n: int) -> int:
        MOD = 1000000007
        a, b = 1, 2
        for _ in range(n - 1):
            a, b = b, (a + b) % MOD
        return b % MOD

class Solution:
    def countNumberOfWaysToPlaceHouses(self, n: int) -> int:
        MOD = 1000000007
        a, b = 1, 1
        for _ in range(n - 1):
            a, b = b, (a + b) % MOD
        return (b * b) % MOD

class Solution:
    def countNumberOfWaysToPlaceHouses(self, n: int) -> int:
        MOD = 1000000007
        a, b = 1, 2
        for _ in range(2 * n - 1):
            a, b = b, (a + b) % MOD
        return b % MOD

